def coerce_value(value: str, expected_type: type) -> Any:
    """Coerce a string to the expected type, raising ConfigError on failure."""
    if expected_type is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError(f"{value!r} is not a valid integer")
    if expected_type is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError(f"{value!r} is not a valid float")
    if expected_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ConfigError(f"{value!r} is not a valid boolean")
    if expected_type is str:
        return value
    raise ConfigError(f"Unsupported type {expected_type}")


def normalize_bool(value: str) -> bool:
    """Normalize a boolean string to True/False."""
    lower = value.lower()
    if lower in ("true", "1", "yes"):
        return True
    if lower in ("false", "0", "no"):
        return False
    raise ConfigError(f"{value!r} is not a valid boolean")


